-- G1 快照迁移：残局门槛 + 谜题全量（幂等）

-- 1) 残局关卡等级门槛（终审 C 项：最低门槛 <= 1000）
UPDATE public.endgame_levels SET elo_required = 0 WHERE id = 1;
UPDATE public.endgame_levels SET elo_required = 950 WHERE id = 2;
UPDATE public.endgame_levels SET elo_required = 1100 WHERE id = 3;
UPDATE public.endgame_levels SET elo_required = 1250 WHERE id = 4;
UPDATE public.endgame_levels SET elo_required = 1400 WHERE id = 5;
UPDATE public.endgame_levels SET elo_required = 1600 WHERE id = 6;
UPDATE public.endgame_levels SET elo_required = 1800 WHERE id = 7;
UPDATE public.endgame_levels SET elo_required = 2000 WHERE id = 8;

-- 2) 战术谜题题库全量快照（58 题）
ON CONFLICT (id) DO UPDATE SET code=EXCLUDED.code, fen=EXCLUDED.fen, side_to_move=EXCLUDED.side_to_move, theme=EXCLUDED.theme, theme_zh=EXCLUDED.theme_zh, theme_en=EXCLUDED.theme_en, difficulty=EXCLUDED.difficulty, rating=EXCLUDED.rating, moves_required=EXCLUDED.moves_required, hint_zh=EXCLUDED.hint_zh, hint_en=EXCLUDED.hint_en, explanation_zh=EXCLUDED.explanation_zh, explanation_en=EXCLUDED.explanation_en, tp_reward=EXCLUDED.tp_reward, diamond_reward=EXCLUDED.diamond_reward, updated_at=now();

-- 3) 谜题解法快照
ON CONFLICT (puzzle_id) DO UPDATE SET solution=EXCLUDED.solution, alternates=EXCLUDED.alternates, updated_at=now();